// 거스름돈 m원을 가장 큰 동전부터 최대한 많이 써서 준다
int coins[] = {500, 100, 50, 10};
int cnt = 0;
for (int c : coins) {
    cnt += m / c;
    m %= c;
}

// 회의 (s, e)들 중 겹치지 않게 고를 수 있는 최대 개수
sort(meet.begin(), meet.end(), [](auto& x, auto& y) {
    if (x.e != y.e) return x.e < y.e;      // 끝나는 시각 순
    return x.s < y.s;
});
int cnt = 0, last = 0;                     // last: 마지막으로 고른 회의가 끝나는 시각
for (auto& m : meet)
    if (m.s >= last) { cnt++; last = m.e; }

// 사람마다 처리 시간 p[i]. 각자 기다린 시간(자기 차례가 끝날 때까지)의 합
sort(p, p + n);                            // 짧은 사람부터
int t = 0, sum = 0;
for (int i = 0; i < n; i++) {
    t += p[i];                             // i번째 사람이 끝나는 시각
    sum += t;
}

// 쪼갤 수 있는 배낭: 무게당 가치가 큰 물건부터 담는다
sort(items, by v / w descending);
double total = 0; int cap = W;
for (auto& it : items) {
    if (cap == 0) break;
    int take = min(cap, it.w);
    total += (double)it.v * take / it.w;
    cap -= take;
}
